// Package store keeps issued battles in SQLite (pure Go driver, no cgo).
// Queries are generated by sqlc from queries.sql: run `go tool sqlc generate`
// in this directory after editing schema.sql or queries.sql.
package store

//go:generate go tool sqlc generate

import (
	"context"
	"database/sql"
	_ "embed"
	"fmt"

	_ "modernc.org/sqlite"
)

//go:embed schema.sql
var schema string

// DB is an open store: the generated queries plus the connection.
type DB struct {
	*Queries
	conn *sql.DB
}

// Open opens (creating if needed) the SQLite file at path and applies the schema.
func Open(ctx context.Context, path string) (*DB, error) {
	conn, err := sql.Open("sqlite", "file:"+path+"?_pragma=journal_mode(WAL)&_pragma=busy_timeout(5000)")
	if err != nil {
		return nil, err
	}
	if _, err := conn.ExecContext(ctx, schema); err != nil {
		conn.Close()
		return nil, fmt.Errorf("applying schema: %w", err)
	}
	return &DB{Queries: New(conn), conn: conn}, nil
}

func (d *DB) Close() error { return d.conn.Close() }
